// HappyDOM smoke host only. This is not a CSS loader for applications or browsers.
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const TOKEN_PREFIX =
  '/* This file is auto-generated by @proto.ui/cli (proto-ui tokens). */\n' +
  '/* Do not edit by hand. */\n\n@layer proto-ui {';
const ENTRY =
  '/* This file is auto-generated by @proto.ui/cli. */\n' +
  '/* Do not edit by hand. */\n' +
  '/* Hosts with named reset or consumer layers must declare their full order before this entry loads. */\n\n' +
  '@layer theme, proto-ui;\n\n' +
  "@import './shadcn-theme.css' layer(theme);\n" +
  "@import './proto-ui-tokens.generated.css';\n";
const FILES = ['proto-ui-style.css', 'shadcn-theme.css', 'proto-ui-tokens.generated.css'];

// Bounded delimiter validation, not a CSS parser: only the generator's exact
// single outer wrapper is accepted. Comments/quoted strings may contain braces.
// Nested @media, @keyframes, etc. are left byte-for-byte intact. Other @layer or
// @import forms fail closed rather than being silently removed or flattened.
export function unwrapGeneratedTokenLayer(css) {
  if (!css.startsWith(TOKEN_PREFIX) || !css.endsWith('\n}\n')) {
    throw new Error('consumer CSS smoke: expected the generated single outer @layer proto-ui');
  }
  const body = css.slice(TOKEN_PREFIX.length, -2);
  assertBoundedBody(body);
  return body;
}

function assertBoundedBody(body) {
  let depth = 0;
  let quote = null;
  let comment = false;
  for (let i = 0; i < body.length; i += 1) {
    const c = body[i];
    const next = body[i + 1];
    if (comment) {
      if (c === '*' && next === '/') {
        comment = false;
        i += 1;
      }
    } else if (quote) {
      if (c === '\\') i += 1;
      else if (c === quote) quote = null;
    } else if (c === '/' && next === '*') {
      comment = true;
      i += 1;
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === '\\') {
      // Escaped identifiers are outside this generator's at-rule vocabulary.
      throw new Error('consumer CSS smoke: unexpected unquoted escape');
    } else if (c === '@' && /^@(layer|import)\b/i.test(body.slice(i))) {
      throw new Error('consumer CSS smoke: additional @layer or @import is unsupported');
    } else if (c === '{') {
      depth += 1;
    } else if (c === '}') {
      depth -= 1;
      if (depth < 0) throw new Error('consumer CSS smoke: unexpected outer CSS structure');
    }
  }
  if (depth !== 0 || quote || comment) {
    throw new Error('consumer CSS smoke: unbalanced generated CSS');
  }
}

export function loadConsumerStyles(
  document,
  { root = process.cwd(), stylesDir = join(root, 'src', 'styles'), evidenceName = 'styled' } = {}
) {
  const originals = FILES.map((name) => ({ name, bytes: readFileSync(join(stylesDir, name)) }));
  if (originals[0].bytes.toString('utf8') !== ENTRY) {
    throw new Error('consumer CSS smoke: unsupported generated entry/import order');
  }
  const theme = originals[1].bytes.toString('utf8');
  assertBoundedBody(theme);
  const tokens = unwrapGeneratedTokenLayer(originals[2].bytes.toString('utf8'));
  const evidenceDir = join(root, 'consumer-css-evidence', evidenceName);
  mkdirSync(evidenceDir, { recursive: true });
  const files = originals.map(({ name, bytes }) => {
    writeFileSync(join(evidenceDir, name), bytes);
    return { name, bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') };
  });
  const limitation =
    'HappyDOM only: explicit theme then token load; single outer proto-ui layer removed. ' +
    'No cascade-layer, width/layout, paint, or native hit-testing equivalence is claimed. ' +
    'Browser/build entry consumes the original complete stylesheet.';
  writeFileSync(
    join(evidenceDir, 'manifest.json'),
    `${JSON.stringify({ files, limitation }, null, 2)}\n`
  );
  const styles = [theme, tokens].map((css, index) => {
    const style = document.createElement('style');
    style.dataset.consumerSmokeCss = index === 0 ? 'theme' : 'tokens';
    style.textContent = css;
    document.head.appendChild(style);
    return style;
  });
  console.log(
    `consumer CSS smoke: ${evidenceName}; originals + SHA-256 at ${evidenceDir}. ${limitation}`
  );
  return { styles, files, evidenceDir };
}

export function assertPositionedSwitch(element, label) {
  if (!element) throw new Error(`${label}: Switch host is missing`);
  const style = element.ownerDocument.defaultView.getComputedStyle(element);
  if (style.position !== 'relative' || style.display !== 'inline-flex') {
    throw new Error(
      `${label}: generated Switch structural CSS not applied: position=${style.position}, display=${style.display}`
    );
  }
}
